Analyze this maintenance request:
Tenant: {{ $json.body.tenant_name }}
Property: {{ $json.body.property_address }}
Issue Description: {{ $json.body.description }}
Photos: {{ $json.body.photos || 'None attached' }}

parameters.jsCode:
// Parse Groq response
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';

// Extract JSON from response
let parsed;
try {
  // Try to find JSON in the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  // Fallback parsing
  parsed = {
    issue_type: 'GENERAL',
    severity: 'routine',
    confidence: 0.5,
    estimated_cost_range: 'medium',
    keywords: ['uncategorized'],
    questions_for_tenant: ['Can you provide more details?'],
    contractor_category: 'general',
    auto_assign: false
  };
}

const webhook = $('Maintenance Webhook').item.json;
const body = webhook.body || {};

return {
  json: {
    // Original request data
    tenant_id: body.tenant_id,
    tenant_name: body.tenant_name,
    tenant_phone: body.tenant_phone,
    tenant_email: body.tenant_email,
    property_id: body.property_id,
    property_address: body.property_address,
    unit_number: body.unit_number,
    issue_description: body.description,
    photos: body.photos || [],
    submitted_at: body.submitted_at || $now,

    // AI classification results
    issue_type: parsed.issue_type || 'GENERAL',
    severity: parsed.severity || 'routine',
    confidence: parsed.confidence || 0.5,
    estimated_cost_range: parsed.estimated_cost_range || 'medium',
    keywords: parsed.keywords || [],
    questions_for_tenant: parsed.questions_for_tenant || [],
    contractor_category: parsed.contractor_category || 'general',
    auto_assign: parsed.auto_assign || false,

    // Routing decisions
    requires_immediate_attention: (parsed.severity === 'emergency') || (parsed.issue_type === 'EMERGENCY'),
    status: parsed.severity === 'emergency' ? 'assigned' : 'open'
  }
};

